
const mongoose = require("mongoose");

const seatSchema = new mongoose.Schema(
  {
    show: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Show",
      required: true,
      index: true,
    },

    theatre: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Theatre",
      required: true,
    },

    screenId: {
      type: mongoose.Schema.Types.ObjectId,
      required: true,
    },

    // Stable physical seat ID generated by the layout.
    // Example: layout-1-A-01
    seatId: {
      type: String,
      required: true,
      trim: true,
    },

    // Customer-facing seat label.
    // Example: A01
    seatLabel: {
      type: String,
      required: true,
      trim: true,
    },

    // Seating geometry
    row: {
      type: String,
      required: true,
      trim: true,
    },

    rowNumber: {
      type: Number,
      required: true,
      min: 1,
    },

    seatNumber: {
      type: Number,
      required: true,
      min: 1,
    },

    columnNumber: {
      type: Number,
      required: true,
      min: 1,
    },

    category: {
      type: String,
      enum: ["regular", "premium", "recliner", "vip"],
      required: true,
    },

    price: {
      type: Number,
      required: true,
      min: 0,
    },

    status: {
      type: String,
      enum: ["available", "locked", "booked", "blocked"],
      default: "available",
      index: true,
    },

    lockToken: {
      type: String,
      default: null,
    },

    lockedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      default: null,
    },

    lockExpiresAt: {
      type: Date,
      default: null,
    },

    booking: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Booking",
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

// One physical seat can exist only once per show.
seatSchema.index(
  { show: 1, seatId: 1 },
  { unique: true }
);

// Availability lookup.
seatSchema.index({ show: 1, status: 1 });

// Expired lock lookup.
seatSchema.index({ status: 1, lockExpiresAt: 1 });

// Render rows in the correct order.
seatSchema.index({
  show: 1,
  rowNumber: 1,
  columnNumber: 1,
});

module.exports = mongoose.model("Seat", seatSchema);
